// THE ACTUAL, UNDERLYING MECHANISM - simplified, but mechanically
// genuine - of what 'server-side rendering' literally does
import { renderToString } from 'react-dom/server';

function WelcomeMessage({ userName, messageCount }: { userName: string; messageCount: number }) {
  return (
    <div>
      <h1>Welcome back, {userName}</h1>
      <p>You have {messageCount} new messages.</p>
    </div>
  );
}

// On the SERVER, when a request for this page arrives:
async function handleRequest(req: Request) {
  const user = await fetchUserData(req.userId); // a genuine,
    // server-side database query, completed BEFORE rendering even begins

  const htmlString = renderToString(
    <WelcomeMessage userName={user.name} messageCount={user.unreadCount} />
  );
  // htmlString is now LITERALLY the string:
  // '<div><h1>Welcome back, Sarah</h1><p>You have 3 new messages.</p></div>'

  return new Response(`
    <!DOCTYPE html>
    <html><body>
      <div id="root">${htmlString}</div>
      <script src="/bundle.js"></script>
    </body></html>
  `);
}

