HYDRATION - the browser-side code that connects lesson 2's static
HTML to a genuinely live, interactive React application:

import { hydrateRoot } from 'react-dom/client';
import { WelcomeMessage } from './WelcomeMessage';

// React WALKS the EXISTING DOM (lesson 2's already-rendered HTML)
// and ATTACHES real event handlers/state, WITHOUT discarding or
// re-creating any of that existing, already-visible markup
hydrateRoot(
  document.getElementById('root')!,
  <WelcomeMessage userName="Sarah" messageCount={3} />
);

STREAMING - directly answering lesson 1's availability question by
sending fast content immediately, slow content as a separate,
later-arriving chunk:

import { Suspense } from 'react';

function DashboardPage() {
  return (
    <div>
      <Header />  {/* FAST, genuinely ready immediately - streamed
                       to the browser right away */}
      <Suspense fallback={<AnalyticsSkeleton />}>
        <SlowAnalyticsWidget />  {/* SLOW - the rest of the page is
          NOT blocked waiting for this; its own HTML streams in as
          a SEPARATE, later chunk once its own data genuinely resolves */}
      </Suspense>
    </div>
  );
}

