// WITHOUT STREAMING - lesson 2's basic SSR pattern, waiting for
// EVERY piece of data before sending ANY html at all
async function handleRequest_noStreaming(req: Request) {
  const headerData = await fetchHeaderData();        // ready in 50ms
  const analyticsData = await fetchSlowAnalytics();   // ready in 4000ms
  // The ENTIRE response is held back until BOTH complete - the
  // genuinely fast headerData provides ZERO benefit to the user,
  // since nothing is sent until the slowest piece ALSO finishes
  const html = renderToString(<DashboardPage header={headerData} analytics={analyticsData} />);
  return new Response(html); // user sees NOTHING for the full 4000ms

// WITH STREAMING - lesson 3's Suspense-based pattern
async function handleRequest_streaming(req: Request) {
  // React's streaming renderer sends the Header's own HTML chunk
  // the MOMENT it's genuinely ready (50ms), independent of
  // analytics' own, separate readiness timeline
  return renderToReadableStream(
    <DashboardPage />, // SlowAnalyticsWidget internally awaits its
                          // own data, wrapped in its OWN Suspense boundary
    { bootstrapScripts: ['/bundle.js'] }
  );
  // RESULT: user sees the Header and an AnalyticsSkeleton placeholder
  // at 50ms; the REAL analytics content streams in and replaces the
  // skeleton automatically once its own 4000ms data genuinely resolves
}

