Design tokens - the single, shared source of truth for genuinely
foundational design values, defined ONCE:

// tokens.ts
export const tokens = {
  colors: {
    primary: '#2563eb',
    danger: '#dc2626',
    text: '#1f2937'
  },
  spacing: {
    sm: '8px',
    md: '16px',
    lg: '24px'
  }
};

A shared, reusable Button component, directly built FROM these
tokens, used by EVERY team rather than each team building their own:

// Button.tsx - the design system's own, single, shared component
import { tokens } from './tokens';

interface ButtonProps {
  variant: 'primary' | 'danger';
  children: React.ReactNode;
  onClick: () => void;
}

export function Button({ variant, children, onClick }: ButtonProps) {
  const backgroundColor = variant === 'primary' ? tokens.colors.primary : tokens.colors.danger;
  return (
    <button
      style={{ backgroundColor, padding: tokens.spacing.md, color: 'white' }}
      onClick={onClick}
    >
      {children}
    </button>
  );
}

// EVERY team, across the entire application, imports and uses THIS
// exact component - never reimplementing their own button from scratch
import { Button } from '@my-org/design-system';
<Button variant="primary" onClick={handleSave}>Save Changes</Button>

